    SORTABLE_ESM = r"""
    function render({ model, el }) {
      const NS = "http://www.w3.org/2000/svg";
      const M = model.get("matrix"), truth = model.get("truth"), n = M.length;
      const PAD = 26, CELL = 19, SIZE = PAD + n * CELL;
      const INK = "#1D1E21", PAPER = "#FFFDF7", RULE = "#D9D2C2";
      const BLUE = "#3959A6", RUST = "#B14434";
      let order = model.get("order").slice();
      let grabbed = null, axis = "row", revealed = false;

      const root = document.createElement("div");
      root.className = "sm";
      const svg = document.createElementNS(NS, "svg");
      svg.setAttribute("viewBox", `0 0 ${SIZE} ${SIZE}`);
      svg.style.cursor = "grab";
      const bar = document.createElement("div");
      bar.className = "sm-bar";
      root.append(svg, bar);
      el.append(root);

      function add(tag, attrs, text) {
        const node = document.createElementNS(NS, tag);
        for (const k in attrs) node.setAttribute(k, attrs[k]);
        if (text !== undefined) node.textContent = text;
        svg.append(node);
      }

      function draw() {
        svg.replaceChildren();
        add("rect", { x: 0, y: 0, width: SIZE, height: SIZE, fill: PAPER });
        const at = grabbed === null ? -1 : order.indexOf(grabbed);
        if (at >= 0) {
          add("rect", { x: PAD, y: PAD + at * CELL, width: n * CELL, height: CELL, fill: BLUE, opacity: 0.16 });
          add("rect", { x: PAD + at * CELL, y: PAD, width: CELL, height: n * CELL, fill: BLUE, opacity: 0.16 });
        }
        for (let k = 1; k < n; k++) {
          const p = PAD + k * CELL;
          add("line", { x1: p, y1: PAD, x2: p, y2: SIZE, stroke: RULE, "stroke-width": 0.5 });
          add("line", { x1: PAD, y1: p, x2: SIZE, y2: p, stroke: RULE, "stroke-width": 0.5 });
        }
        for (let a = 0; a < n; a++)
          for (let b = 0; b < n; b++)
            if (M[order[a]][order[b]])
              add("rect", { x: PAD + b * CELL, y: PAD + a * CELL, width: CELL, height: CELL, fill: INK });
        add("rect", { x: PAD, y: PAD, width: n * CELL, height: n * CELL, fill: "none", stroke: INK, "stroke-width": 1.4 });
        if (revealed)
          for (let a = 1; a < n; a++)
            if (truth[order[a]] !== truth[order[a - 1]]) {
              const p = PAD + a * CELL;
              add("line", { x1: p, y1: PAD, x2: p, y2: SIZE, stroke: RUST, "stroke-width": 2.2 });
              add("line", { x1: PAD, y1: p, x2: SIZE, y2: p, stroke: RUST, "stroke-width": 2.2 });
            }
        for (let a = 0; a < n; a++) {
          const mid = PAD + (a + 0.5) * CELL;
          const on = order[a] === grabbed;
          const style = { "font-size": 9.5, "font-family": "system-ui,sans-serif", "font-weight": 700, fill: on ? BLUE : INK };
          add("text", { ...style, x: mid, y: PAD - 8, "text-anchor": "middle" }, order[a] + 1);
          add("text", { ...style, x: PAD - 6, y: mid + 3.4, "text-anchor": "end" }, order[a] + 1);
        }
      }

      function commit() {
        draw();
        model.set("order", order.slice());
        model.save_changes();
      }

      function where(ev) {
        const r = svg.getBoundingClientRect(), k = SIZE / r.width;
        return [(ev.clientX - r.left) * k, (ev.clientY - r.top) * k];
      }

      svg.addEventListener("pointerdown", (ev) => {
        const [x, y] = where(ev);
        let idx = -1;
        if (y >= PAD) { axis = "row"; idx = Math.floor((y - PAD) / CELL); }
        else if (x >= PAD) { axis = "col"; idx = Math.floor((x - PAD) / CELL); }
        if (idx < 0 || idx >= n) return;
        grabbed = order[idx];
        revealed = false;
        svg.style.cursor = "grabbing";
        svg.setPointerCapture(ev.pointerId);
        draw();
        ev.preventDefault();
      });

      svg.addEventListener("pointermove", (ev) => {
        if (grabbed === null) return;
        const [x, y] = where(ev);
        const to = Math.max(0, Math.min(n - 1, Math.floor(((axis === "row" ? y : x) - PAD) / CELL)));
        const from = order.indexOf(grabbed);
        if (to !== from) {
          order.splice(from, 1);
          order.splice(to, 0, grabbed);
          draw();
        }
      });

      function drop() {
        if (grabbed === null) return;
        grabbed = null;
        svg.style.cursor = "grab";
        commit();
      }
      svg.addEventListener("pointerup", drop);
      svg.addEventListener("pointercancel", drop);

      function button(label, fn) {
        const b = document.createElement("button");
        b.textContent = label;
        b.addEventListener("click", fn);
        bar.append(b);
      }
      const ids = () => Array.from({ length: n }, (_, i) => i);
      button("Start over", () => { order = ids(); revealed = false; commit(); });
      button("Show answer", () => { order = ids().sort((a, b) => truth[a] - truth[b] || a - b); revealed = true; commit(); });

      draw();
    }
    export default { render };
    """

    SORTABLE_CSS = """
    .sm { width: 100%; max-width: 360px; font-family: system-ui, sans-serif; }
    .sm svg { width: 100%; display: block; touch-action: none; user-select: none;
              border: 1.5px solid #D9D2C2; border-radius: 6px; }
    .sm-bar { display: flex; gap: 8px; margin-top: 6px; }
    .sm-bar button { font: inherit; font-size: 13px; padding: 3px 10px; cursor: pointer;
                     border: 1.5px solid #1D1E21; border-radius: 6px;
                     background: #FFFDF7; color: #1D1E21; }
    .sm-bar button:hover { background: #F1ECDD; }
    """

    class SortableMatrix(anywidget.AnyWidget):
        _esm = SORTABLE_ESM
        _css = SORTABLE_CSS
        matrix = traitlets.List().tag(sync=True)  # n x n, 0 or 1, in node order
        truth = traitlets.List().tag(sync=True)  # the group of each node
        order = traitlets.List().tag(sync=True)  # the order on the page now

    # ---- words and boxes ------------------------------------------------------

    def note(text, tone=BLUE):
        return mo.Html(
            f'<div style="border-left:3px solid {tone};padding:2px 0 2px 14px;'
            f'margin:14px 0;font-family:{SANS};font-size:16px;color:{INK}">{text}</div>'
        )

    WAITING = mo.Html(
        f'<div style="font-family:{SANS};font-size:15px;color:#6A6D75;'
        f'border:1.5px dashed {RULE};border-radius:{WOBBLE};padding:10px 14px;'
        'display:inline-block">Waiting on the cell above.</div>'
    )

    def type_me(src):
        """A block of code to read and type. It cannot be selected, so it
        cannot be pasted."""
        return mo.Html(
            f'<pre style="user-select:none;-webkit-user-select:none;cursor:default;'
            f"font-family:{MONO};font-size:13.5px;line-height:1.5;margin:10px 0;"
            f"padding:10px 14px;background:{PAPER};border:1.5px solid {RULE};"
            f'border-radius:{WOBBLE};color:{INK};overflow-x:auto">{html.escape(inspect.cleandoc(src))}</pre>'
        )

    def is_list_of(x, n):
        """True when x is a list with one entry per node."""
        return isinstance(x, (list, tuple)) and len(x) == n

    # ---- drawing --------------------------------------------------------------

    def albers(lon, lat, lon0=-96.0, lat0=37.5, p1=29.5, p2=45.5):
        """The map projection the US usually gets: Albers equal-area conic.
        Done by hand so that no map library has to be installed."""
        lon, lat = np.radians(np.asarray(lon, float)), np.radians(np.asarray(lat, float))
        n = (math.sin(math.radians(p1)) + math.sin(math.radians(p2))) / 2
        c = math.cos(math.radians(p1)) ** 2 + 2 * n * math.sin(math.radians(p1))
        rho = np.sqrt(c - 2 * n * np.sin(lat)) / n
        rho0 = math.sqrt(c - 2 * n * math.sin(math.radians(lat0))) / n
        theta = n * (lon - math.radians(lon0))
        return rho * np.sin(theta), rho0 - rho * np.cos(theta)

    AIR_X, AIR_Y = albers([a[3] for a in AIR], [a[2] for a in AIR])

    def draw_outline(ax):
        for ring in DATA["states"]:
            x, y = albers([p[0] for p in ring], [p[1] for p in ring])
            ax.plot(x, y, color=GREY, lw=0.5, zorder=0)

    def edge_matrix(n, edges):
        M = np.zeros((n, n), dtype=np.int8)
        for i, j in edges:
            M[i, j] = M[j, i] = 1
        return M

    def rank_blocks(blocks, weight):
        """Relabel the blocks 0, 1, 2, ... with the one whose members have the
        highest `weight` first. Busiest block first."""
        blocks = np.asarray(blocks)
        ids = sorted(set(blocks.tolist()), key=lambda r: -weight[blocks == r].mean())
        rank = {r: k for k, r in enumerate(ids)}
        return np.array([rank[b] for b in blocks.tolist()])

    def cuts_of(b):
        return list(np.cumsum(np.bincount(b))[:-1])

    def figure(rows, cols, height, ratios=None):
        fig, axs = plt.subplots(
            rows, cols, figsize=(8, height), facecolor=PAPER,
            gridspec_kw=dict(width_ratios=ratios) if ratios else None,
        )  # fmt: skip
        for ax in np.atleast_1d(axs).ravel():
            ax.set_facecolor(PAPER)
        return fig, axs

    def finish(fig):
        fig.tight_layout()
        plt.close(fig)
        return fig

    def draw_dots(ax, M, rows, cols, s, cuts_r=(), cuts_c=(), title=None):
        sub = M[np.ix_(rows, cols)]
        r, c = np.nonzero(sub)
        ax.scatter(c, r, s=s, marker="s", linewidths=0, color=INK, rasterized=True)
        for k in cuts_c:
            ax.axvline(k - 0.5, color=RUST, lw=0.7, alpha=0.7)
        for k in cuts_r:
            ax.axhline(k - 0.5, color=RUST, lw=0.7, alpha=0.7)
        ax.set_xlim(-0.5, len(cols) - 0.5)
        ax.set_ylim(len(rows) - 0.5, -0.5)
        ax.set_aspect("equal")
        ax.set_xticks([])
        ax.set_yticks([])
        for side in ax.spines.values():
            side.set_color(GREY)
        if title:
            ax.set_title(title, fontsize=9, color=INK, loc="left")

    def blocks_figure(M, panels, s):
        """One matrix per panel, side by side. A panel is (title, blocks): the
        nodes are listed block by block, the busiest block first, and the
        blocks are cut by red lines. No blocks: the order the nodes came in."""
        deg = M.sum(axis=1)
        fig, axs = plt.subplots(
            1, len(panels), figsize=(4.2 * len(panels), 4.2), facecolor=PAPER
        )
        for ax, (title, blocks) in zip(np.atleast_1d(axs), panels):
            ax.set_facecolor(PAPER)
            if blocks is None:
                order, cuts = np.arange(len(deg)), []
            else:
                b = rank_blocks(blocks, deg)
                order, cuts = np.lexsort((-deg, b)), cuts_of(b)
                title = f"{title}: {b.max() + 1} blocks"
            draw_dots(ax, M, order, order, s, cuts, cuts, title=title)
        return finish(fig)


