@app.cell(hide_code=True)
def _():
    _M = edge_matrix(AIR_N, AIR_EDGES)
    _deg = _M.sum(axis=1)
    _fig, _axs = figure(1, 2, 3.7, ratios=[1.7, 1])
    _ax = _axs[0]
    draw_outline(_ax)
    _segs = [[(AIR_X[i], AIR_Y[i]), (AIR_X[j], AIR_Y[j])] for i, j in AIR_EDGES]
    _ax.add_collection(LineCollection(_segs, colors=INK, linewidths=0.35, alpha=0.12))
    _ax.scatter(AIR_X, AIR_Y, s=2 + 1.6 * np.sqrt(_deg), color=RUST, lw=0, zorder=3)
    _ax.set_aspect("equal")
    _ax.axis("off")
    _ax.set_title("where the airports are", fontsize=9, color=INK, loc="left")
    draw_dots(_axs[1], _M, list(range(AIR_N)), list(range(AIR_N)), 0.9,
              title="A→Z order")  # fmt: skip
    finish(_fig)
    return


