@app.cell(hide_code=True)
def _(sure):
    if sure is ...:
        _out = WAITING
    elif not is_list_of(sure, AIR_N):
        _out = note(
            "Not yet. <code>sure</code> should hold one number per airport.", RUST
        )
    else:
        _deg = edge_matrix(AIR_N, AIR_EDGES).sum(axis=1)
        _doubt = 1 - np.asarray(sure, dtype=float)
        _fig, _axs = figure(1, 2, 3.5, ratios=[1.5, 1])
        _ax = _axs[0]
        draw_outline(_ax)
        _hot = _doubt > 0.2
        _ax.scatter(AIR_X[~_hot], AIR_Y[~_hot], s=4, color=GREY, lw=0, zorder=2)
        _ax.scatter(AIR_X[_hot], AIR_Y[_hot], s=4 + 40 * _doubt[_hot], color=RUST,
                    lw=0, alpha=0.8, zorder=3)  # fmt: skip
        _ax.set_aspect("equal")
        _ax.axis("off")
        _ax.set_title("red: out of its usual block in more than a fifth of the draws",
                      fontsize=9, color=INK, loc="left")  # fmt: skip
        _ax = _axs[1]
        _jitter = np.random.default_rng(0).uniform(-0.12, 0.12, AIR_N)
        _ax.scatter(_deg * 10 ** _jitter, _doubt, s=6, lw=0, alpha=0.7,
                    color=[RUST if h else GREY for h in _hot])  # fmt: skip
        _ax.set_xscale("log")
        _ax.set_xlabel("number of routes", fontsize=8, color=INK)
        _ax.set_ylabel("how often not in its usual block", fontsize=8, color=INK)
        _ax.tick_params(labelsize=7, colors=INK)
        for _side in ("top", "right"):
            _ax.spines[_side].set_visible(False)
        for _side in ("left", "bottom"):
            _ax.spines[_side].set_color(GREY)
        _out = mo.vstack(
            [
                mo.md(f"**{int(_hot.sum())} of {AIR_N} airports** are red."),
                finish(_fig),
            ]
        )
    _out
    return


